let raw = [];
try {
  const gdeltItem = $('GDELT DOC Search').first();
  raw = (gdeltItem && gdeltItem.json && gdeltItem.json.articles) || [];
} catch (e) {
  raw = [];
}
const possiblyTruncated = raw.length === 250;

let existingUrls;
try {
  existingUrls = new Set($('Get Existing URLs').all().map(i => i.json.source_url).filter(Boolean));
} catch (e) {
  existingUrls = new Set();
}

const seenInBatch = new Set();
const results = [];

for (const a of raw) {
  const url = a.url || null;
  if (!url) continue;
  if (existingUrls.has(url) || seenInBatch.has(url)) continue;
  seenInBatch.add(url);

  results.push({
    json: {
      title: a.title || null,
      source_url: url,
      mobile_url: a.url_mobile || null,
      source_domain: a.domain || null,
      source_country: a.sourcecountry || null,
      language: a.language || null,
      gdelt_seen_at: a.seendate || null,
      social_image_url: a.socialimage || null,
      collection_source: 'GDELT_DOC_2',
      full_text: null,
      crawl_status: 'not_attempted',
      query_topic: 'asean_southeast_asia_south_china_sea',
      window_possibly_truncated: possiblyTruncated,
      fetched_at: new Date().toISOString()
    }
  });
}

return results;
